{{(() => {
     // The settlement the merchant will see on the order, before Създай: priced by the
     // server with the same code as the real order (PortalQuote), laid out like the
     // console's box - total to collect, then goods · delivery · НП fee (2026-10-02).
     const en = appsmith.store.bo_lang === 'en';
     const cod = NewPaymentMethodSelect.selectedOptionValue === 'COD';
     const eur = (v) => Number(v || 0).toLocaleString('bg-BG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
     const typed = String(NewAmountInput.text || '0').trim().replace(',', '.');
     const head = cod
       ? (en ? 'Total to collect: ' : 'Сума за събиране: ') + eur(typed)
       : (en ? 'Prepaid order' : 'Поръчката е платена предварително');
     if (!OrderShippingSelect.selectedOptionValue) {
       return head + '\n' + (en ? 'Choose the delivery type to see the fees' : 'Изберете вид доставка, за да видите таксите');
     }
     if (PortalQuote.isLoading) return head + '\n…';
     const q = PortalQuote.data || {};
     if (!q.delivery) return head;
     if (!cod) return head + '\n' + (en ? 'Delivery ' : 'Доставка ') + eur(q.delivery);
     return head + '\n' + (en ? 'COD amount (goods) ' : 'Стока (наложен платеж) ') + eur(q.goods)
       + ' · ' + (en ? 'delivery ' : 'доставка ') + eur(q.delivery)
       + ' · ' + (en ? 'COD fee ' : 'такса НП ') + eur(q.cod_fee);
   })()}}
